import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as d,o,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Grok Build Cheatsheet","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/grok/grok-cheatsheet.md","filePath":"products/ai-coding/grok/grok-cheatsheet.md","lastUpdated":1787042982000}'),a={name:"products/ai-coding/grok/grok-cheatsheet.md"};function s(c,t,i,n,l,h){return o(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="grok-build-cheatsheet" tabindex="-1">Grok Build Cheatsheet <a class="header-anchor" href="#grok-build-cheatsheet" aria-label="Permalink to &quot;Grok Build Cheatsheet&quot;">​</a></h1><p>Lookup only, no teaching. Every entry comes from xAI&#39;s official documentation, with the source page linked next to each section heading. The authoritative full command set is always <code>grok --help</code> / <code>grok &lt;subcommand&gt; --help</code>.</p><p>Covers npm <code>@xai-official/grok</code> <code>1.0.5</code> (<code>dist-tags.latest</code> and <code>alpha</code> as of 2026-08-16). The <a href="https://x.ai/build/changelog" target="_blank" rel="noreferrer">changelog</a> header still showed v1.0.3 / Aug 12, 2026 when re-checked on 2026-08-18. If something does not match, run <code>grok version</code> and check the changelog.</p><h2 id="install-and-update" tabindex="-1">Install and update <a class="header-anchor" href="#install-and-update" aria-label="Permalink to &quot;Install and update&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Command</th></tr></thead><tbody><tr><td>macOS / Linux</td><td><code>curl -fsSL https://x.ai/cli/install.sh | bash</code></td></tr><tr><td>Windows PowerShell</td><td><code>irm https://x.ai/cli/install.ps1 | iex</code></td></tr><tr><td>npm channel</td><td><code>npm install -g @xai-official/grok</code></td></tr><tr><td>Check for updates</td><td><code>grok update --check</code></td></tr><tr><td>Install a specific version</td><td><code>grok update --version &lt;V&gt;</code></td></tr><tr><td>Switch channel</td><td><code>grok update --alpha</code> / <code>grok update --stable</code></td></tr><tr><td>Show version</td><td><code>grok version</code></td></tr></tbody></table><p>The npm package requires <code>node &gt;= 20</code>; the binary is named <code>grok</code>.</p><h2 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;Subcommands&quot;">​</a></h2><p>Source: <a href="https://docs.x.ai/build/cli/reference" target="_blank" rel="noreferrer">CLI Reference</a></p><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>grok</code></td><td>No arguments starts the interactive TUI</td></tr><tr><td><code>grok login</code></td><td>Log in; <code>--device-auth</code> uses the device-code flow (no browser)</td></tr><tr><td><code>grok logout</code></td><td>Log out and clear cached credentials</td></tr><tr><td><code>grok inspect [--json]</code></td><td>Show what was discovered in this directory: rules, skills, plugins, hooks, MCP servers</td></tr><tr><td><code>grok models</code></td><td>List available models</td></tr><tr><td><code>grok mcp &lt;list|add|remove|doctor&gt;</code></td><td>Manage MCP servers</td></tr><tr><td><code>grok plugin &lt;list|install|uninstall|update|enable|disable|details|validate&gt;</code></td><td>Manage plugins</td></tr><tr><td><code>grok plugin marketplace &lt;list|add|remove|update&gt;</code></td><td>Manage marketplace sources</td></tr><tr><td><code>grok sessions &lt;list|search|delete&gt;</code></td><td>List, search, delete sessions</td></tr><tr><td><code>grok export &lt;session-id&gt; [output]</code></td><td>Export a session as Markdown</td></tr><tr><td><code>grok import [targets...]</code></td><td>Import sessions from Claude Code</td></tr><tr><td><code>grok memory clear [--workspace|--global|--all]</code></td><td>Clear cross-session memory files</td></tr><tr><td><code>grok worktree &lt;list|show|rm|gc&gt;</code></td><td>Manage git worktrees created by sessions</td></tr><tr><td><code>grok dashboard</code></td><td>Open the Agent Dashboard</td></tr><tr><td><code>grok agent stdio</code></td><td>Run as an ACP agent over stdin/stdout</td></tr><tr><td><code>grok wrap &lt;command...&gt;</code></td><td>Run a command in a local PTY, forwarding OSC 52 clipboard writes</td></tr><tr><td><code>grok update</code></td><td>Check for or install updates</td></tr><tr><td><code>grok version</code></td><td>Print version information</td></tr><tr><td><code>grok completions &lt;shell&gt;</code></td><td>Generate a shell completion script</td></tr><tr><td><code>grok setup</code></td><td>Fetch and install managed configuration</td></tr></tbody></table><h2 id="common-flags" tabindex="-1">Common flags <a class="header-anchor" href="#common-flags" aria-label="Permalink to &quot;Common flags&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Flag</th><th>Purpose</th></tr></thead><tbody><tr><td><code>--cwd &lt;PATH&gt;</code></td><td>Working directory</td></tr><tr><td><code>-r, --resume [&lt;ID&gt;]</code></td><td>Resume a session; omit the ID for the most recent</td></tr><tr><td><code>-c, --continue</code></td><td>Continue the most recent session in this directory</td></tr><tr><td><code>-s, --session-id &lt;UUID&gt;</code></td><td>Assign a UUID to a <strong>new</strong> session (not a resume)</td></tr><tr><td><code>--fork-session</code></td><td>Fork into a new session ID when resuming</td></tr><tr><td><code>-w, --worktree [&lt;NAME&gt;]</code></td><td>Start the session in a new git worktree</td></tr><tr><td><code>--ref &lt;REF&gt;</code></td><td>Branch / tag / commit the worktree is based on</td></tr><tr><td><code>-m, --model &lt;MODEL&gt;</code></td><td>Model ID</td></tr><tr><td><code>--effort &lt;LEVEL&gt;</code></td><td>Reasoning effort</td></tr><tr><td><code>--always-approve</code></td><td>Auto-approve all tool calls (alias <code>--yolo</code>)</td></tr><tr><td><code>--allow &lt;RULE&gt;</code> / <code>--deny &lt;RULE&gt;</code></td><td>Permission rules</td></tr><tr><td><code>--sandbox &lt;PROFILE&gt;</code></td><td>Sandbox profile</td></tr><tr><td><code>--rules &lt;TEXT&gt;</code></td><td>Extra rules appended to the system prompt</td></tr><tr><td><code>--system-prompt-override &lt;TEXT&gt;</code></td><td>Replace the system prompt entirely</td></tr><tr><td><code>--tools &lt;LIST&gt;</code> / <code>--disallowed-tools &lt;LIST&gt;</code></td><td>Expose or remove built-in tools</td></tr><tr><td><code>--max-turns &lt;N&gt;</code></td><td>Maximum agent turns</td></tr><tr><td><code>--no-plan</code> / <code>--no-subagents</code> / <code>--no-memory</code> / <code>--disable-web-search</code></td><td>Disable a feature for this session</td></tr><tr><td><code>--experimental-memory</code></td><td>Enable cross-session memory</td></tr><tr><td><code>--oauth</code></td><td>Use OAuth on the welcome-screen auth flow</td></tr><tr><td><code>--trust</code></td><td>Trust project-level hooks / MCP / LSP at startup</td></tr><tr><td><code>--plugin-dir &lt;PATH&gt;</code></td><td>Additional plugin directory</td></tr></tbody></table><p>Claude Code flag names are accepted as aliases: <code>--allowedTools</code>, <code>--disallowedTools</code>, <code>--append-system-prompt</code>, <code>--system-prompt</code>, <code>--dangerously-skip-permissions</code>.</p><h3 id="headless-specific" tabindex="-1">Headless-specific <a class="header-anchor" href="#headless-specific" aria-label="Permalink to &quot;Headless-specific&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Flag</th><th>Purpose</th></tr></thead><tbody><tr><td><code>-p &lt;PROMPT&gt;</code></td><td>Run one prompt non-interactively</td></tr><tr><td><code>--output-format plain|json|streaming-json</code></td><td>Output format, default <code>plain</code></td></tr><tr><td><code>--permission-mode dontAsk|acceptEdits</code></td><td>Permission mode for CI</td></tr><tr><td><code>--no-alt-screen</code></td><td>Do not use the alternate screen buffer</td></tr><tr><td><code>--no-auto-update</code></td><td>Skip auto-update for this run</td></tr></tbody></table><h2 id="permissions-and-modes" tabindex="-1">Permissions and modes <a class="header-anchor" href="#permissions-and-modes" aria-label="Permalink to &quot;Permissions and modes&quot;">​</a></h2><p>Sources: <a href="https://docs.x.ai/build/features/permissions" target="_blank" rel="noreferrer">Permissions</a>, <a href="https://docs.x.ai/build/modes-and-commands" target="_blank" rel="noreferrer">Modes and Commands</a></p><table tabindex="0"><thead><tr><th>Mode</th><th>Behavior</th><th>How to enter</th></tr></thead><tbody><tr><td>Ask (default)</td><td>Anything not allowed prompts</td><td>Default</td></tr><tr><td>Auto</td><td>A classifier auto-approves safe tools; dangerous ones may still prompt</td><td><code>/auto</code>, <code>Shift+Tab</code> (when enabled)</td></tr><tr><td>Always-approve</td><td>Auto-approves tool calls (<code>deny</code> rules and <code>PreToolUse</code> hooks still apply)</td><td><code>/always-approve</code>, <code>Ctrl+O</code>, <code>Shift+Tab</code>, <code>grok --always-approve</code></td></tr><tr><td>Plan</td><td>Only the session plan file is editable until you approve</td><td><code>/plan [description]</code>, <code>Shift+Tab</code></td></tr><tr><td><code>dontAsk</code></td><td>Silently denies anything without an explicit allow (headless / CI)</td><td><code>--permission-mode dontAsk</code></td></tr><tr><td><code>acceptEdits</code></td><td>Auto-approves file edits, still asks for shell commands</td><td><code>--permission-mode acceptEdits</code></td></tr></tbody></table><p><code>Shift+Tab</code> cycles: Normal → Plan → Auto (when available) → Always-approve.</p><p>Rule syntax (<code>deny</code> always beats <code>allow</code>):</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rules = [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { action = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, tool = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, pattern = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;git *&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { action = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;allow&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, tool = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;read&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  { action = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deny&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  tool = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;bash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, pattern = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rm -rf *&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Supported filters: <code>Bash</code>, <code>Edit</code>, <code>Read</code>, <code>Grep</code>, <code>MCPTool</code>, <code>WebFetch</code>, <code>WebSearch</code>.</p><p><code>[ui] permission_mode</code> only takes effect in <strong>user</strong> configuration (<code>~/.grok/config.toml</code>, or managed / requirements files); setting it in a project <code>.grok/config.toml</code> does nothing. The legacy keys <code>approval_mode</code> and <code>yolo = true</code> still work; when both are set, <code>permission_mode</code> wins.</p><h2 id="sandbox-profiles" tabindex="-1">Sandbox profiles <a class="header-anchor" href="#sandbox-profiles" aria-label="Permalink to &quot;Sandbox profiles&quot;">​</a></h2><p>Source: <a href="https://docs.x.ai/build/features/sandbox" target="_blank" rel="noreferrer">Sandbox</a></p><p>Off by default. Landlock on Linux, Seatbelt on macOS.</p><table tabindex="0"><thead><tr><th>Profile</th><th>Read</th><th>Write</th><th>Network</th><th>Positioning</th></tr></thead><tbody><tr><td><code>off</code></td><td>Unrestricted</td><td>Unrestricted</td><td>Allowed</td><td>No sandbox (default)</td></tr><tr><td><code>workspace</code></td><td>Anywhere</td><td>CWD, <code>~/.grok/</code>, temp dirs</td><td>Allowed</td><td>Normal development</td></tr><tr><td><code>devbox</code></td><td>Anywhere</td><td>Top-level dirs except <code>/data</code></td><td>Allowed</td><td>Cloud dev machine</td></tr><tr><td><code>read-only</code></td><td>Anywhere</td><td>Only <code>~/.grok/</code> and temp dirs</td><td>Blocked</td><td>Code review, audit</td></tr><tr><td><code>strict</code></td><td>CWD and system paths</td><td>CWD, <code>~/.grok/</code>, temp dirs</td><td>Blocked</td><td>Untrusted repos</td></tr></tbody></table><p>Three limitations: subprocess network restrictions <strong>only apply on Linux</strong> (on macOS the blocking in <code>read-only</code> / <code>strict</code> is a no-op); built-in profiles do <strong>not</strong> permanently protect paths like <code>~/.ssh</code>, so write your own <code>deny</code> list; <code>~/.grok/</code> stays writable under every profile. The model API and web tools are unaffected by subprocess network settings.</p><p>Custom profiles go in <code>~/.grok/sandbox.toml</code> or <code>.grok/sandbox.toml</code>; built-in names cannot be redefined:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">profiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my-profile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">extends = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workspace&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">restrict_network = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">deny = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/secrets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/.env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/*.pem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="slash-commands" tabindex="-1">Slash commands <a class="header-anchor" href="#slash-commands" aria-label="Permalink to &quot;Slash commands&quot;">​</a></h2><p>Source: <a href="https://docs.x.ai/build/modes-and-commands" target="_blank" rel="noreferrer">Modes and Commands</a></p><h3 id="session" tabindex="-1">Session <a class="header-anchor" href="#session" aria-label="Permalink to &quot;Session&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/quit</code> (alias <code>/exit</code>)</td><td>Quit</td></tr><tr><td><code>/help</code></td><td>Browse commands and key bindings</td></tr><tr><td><code>/home</code></td><td>Back to the welcome screen</td></tr><tr><td><code>/new</code> (alias <code>/clear</code>)</td><td>New session</td></tr><tr><td><code>/resume</code></td><td>Resume a past session</td></tr><tr><td><code>/sessions</code></td><td>Switch, rename, close active sessions</td></tr><tr><td><code>/fork</code></td><td>Fork the current session into a peer agent</td></tr><tr><td><code>/rename &lt;title&gt;</code> (alias <code>/title</code>)</td><td>Rename the current session</td></tr><tr><td><code>/share</code></td><td>Share the current session as a URL</td></tr><tr><td><code>/session-info</code></td><td>Session information</td></tr><tr><td><code>/context</code></td><td>Context usage</td></tr><tr><td><code>/compact [context]</code></td><td>Compact conversation history</td></tr><tr><td><code>/rewind</code></td><td>Roll back to an earlier turn</td></tr><tr><td><code>/export</code></td><td>Export the conversation to a file or the clipboard</td></tr><tr><td><code>/copy [N]</code></td><td>Copy the last (or Nth-from-last) response</td></tr><tr><td><code>/find</code></td><td>Search the scrollback</td></tr><tr><td><code>/transcript</code></td><td>View the full transcript with <code>$PAGER</code></td></tr></tbody></table><h3 id="models-and-modes" tabindex="-1">Models and modes <a class="header-anchor" href="#models-and-modes" aria-label="Permalink to &quot;Models and modes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/model &lt;name&gt;</code> (alias <code>/m</code>)</td><td>Switch model</td></tr><tr><td><code>/effort</code></td><td>Set reasoning effort for the current model</td></tr><tr><td><code>/always-approve</code></td><td>Toggle always-approve</td></tr><tr><td><code>/auto</code></td><td>Toggle auto mode</td></tr><tr><td><code>/plan [description]</code></td><td>Enter plan mode</td></tr><tr><td><code>/view-plan</code></td><td>View the current plan</td></tr></tbody></table><h3 id="tasks-and-orchestration" tabindex="-1">Tasks and orchestration <a class="header-anchor" href="#tasks-and-orchestration" aria-label="Permalink to &quot;Tasks and orchestration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/btw &lt;question&gt;</code></td><td>Ask a side question without derailing the main thread</td></tr><tr><td><code>/loop [interval] &lt;prompt&gt;</code></td><td>Repeat a prompt on an interval</td></tr><tr><td><code>/tasks</code></td><td>List background tasks, subagents, scheduled jobs</td></tr><tr><td><code>/queue</code></td><td>List prompts queued behind the current turn</td></tr><tr><td><code>/create-workflow [description]</code></td><td>Write and save a new workflow</td></tr><tr><td><code>/workflow &lt;name&gt; [args]</code></td><td>Start a workflow, or <code>pause</code> / <code>resume</code> / <code>stop</code> / <code>save</code></td></tr><tr><td><code>/workflows</code></td><td>Full-screen workflow run board</td></tr><tr><td><code>/deep-research &lt;query&gt;</code></td><td>Run the built-in research workflow</td></tr><tr><td><code>/dashboard</code></td><td>Open the Agent Dashboard</td></tr><tr><td><code>/imagine &lt;prompt&gt;</code></td><td>Text to image</td></tr><tr><td><code>/imagine-video &lt;prompt&gt;</code></td><td>Text to video</td></tr></tbody></table><h3 id="extensions-and-configuration" tabindex="-1">Extensions and configuration <a class="header-anchor" href="#extensions-and-configuration" aria-label="Permalink to &quot;Extensions and configuration&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/hooks</code> / <code>/plugins</code> / <code>/marketplace</code> / <code>/skills</code> / <code>/mcps</code></td><td>Different tabs of the same extensions dialog</td></tr><tr><td><code>/config-agents</code> (alias <code>/agents</code>)</td><td>Manage agent definitions</td></tr><tr><td><code>/personas</code></td><td>Manage personas</td></tr><tr><td><code>/settings</code> (alias <code>/config</code>)</td><td>Settings dialog</td></tr><tr><td><code>/theme [name]</code> (alias <code>/t</code>)</td><td>Switch theme</td></tr><tr><td><code>/compact-mode</code></td><td>More compact UI</td></tr><tr><td><code>/multiline</code> (alias <code>/ml</code>)</td><td>Toggle multiline input</td></tr><tr><td><code>/vim-mode</code></td><td>Toggle vim-style scrollback keys</td></tr><tr><td><code>/timestamps</code></td><td>Toggle message timestamps</td></tr><tr><td><code>/terminal-setup</code></td><td>Check terminal and clipboard configuration</td></tr><tr><td><code>/hooks-trust</code></td><td>Trust the current project&#39;s hooks</td></tr><tr><td><code>/import-claude</code></td><td>Open the Claude settings-import dialog</td></tr></tbody></table><h3 id="account-and-memory" tabindex="-1">Account and memory <a class="header-anchor" href="#account-and-memory" aria-label="Permalink to &quot;Account and memory&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/login</code> / <code>/logout</code></td><td>Log in / out</td></tr><tr><td><code>/usage</code></td><td>View quota usage or manage billing</td></tr><tr><td><code>/privacy</code></td><td>View or change privacy and data-retention status</td></tr><tr><td><code>/feedback [text]</code></td><td>Send feedback about the current session</td></tr><tr><td><code>/release-notes</code> (alias <code>/changelog</code>)</td><td>Release notes for the current version</td></tr><tr><td><code>/remember &lt;note&gt;</code></td><td>Store a memory</td></tr><tr><td><code>/flush</code></td><td>Write conversation memory to disk now</td></tr><tr><td><code>/memory</code> (alias <code>/mem</code>)</td><td>Browse and manage memories</td></tr><tr><td><code>/dream</code></td><td>Run memory consolidation</td></tr></tbody></table><p><code>/flush</code>, <code>/memory</code>, and <code>/dream</code> are provided by the shell and only appear when cross-session memory is enabled. User-invocable skills also become <code>/&lt;skill-name&gt;</code>; on a name collision use the qualified form such as <code>/local:commit</code>.</p><h2 id="key-bindings" tabindex="-1">Key bindings <a class="header-anchor" href="#key-bindings" aria-label="Permalink to &quot;Key bindings&quot;">​</a></h2><p>Source: <a href="https://docs.x.ai/build/keyboard-shortcuts" target="_blank" rel="noreferrer">Keyboard Shortcuts</a>. Press <code>Ctrl+.</code> in the TUI for the full list (<code>Ctrl+X</code> on Windows or terminals without Kitty keyboard protocol support).</p><h3 id="essential" tabindex="-1">Essential <a class="header-anchor" href="#essential" aria-label="Permalink to &quot;Essential&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Send</td></tr><tr><td><code>Tab</code></td><td>Move focus between the input box and the scrollback</td></tr><tr><td><code>Esc</code></td><td>Cancel the running turn</td></tr><tr><td><code>Esc Esc</code></td><td>Clear the input box; opens rewind when the input is empty</td></tr><tr><td><code>Ctrl+C</code></td><td>Cancel the turn</td></tr><tr><td><code>Shift+Tab</code></td><td>Cycle modes</td></tr><tr><td><code>Ctrl+P</code> or <code>?</code></td><td>Command palette</td></tr><tr><td><code>F2</code> or <code>Ctrl+,</code></td><td>Settings</td></tr><tr><td><code>Ctrl+Q</code> / <code>Ctrl+D</code></td><td>Quit (press twice)</td></tr></tbody></table><h3 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+Enter</code> or <code>Ctrl+I</code></td><td>Interject during a running turn</td></tr><tr><td><code>Shift+Enter</code></td><td>Newline; sends in multiline mode (use <code>Alt+Enter</code> where unsupported)</td></tr><tr><td><code>Ctrl+M</code></td><td>Toggle multiline input</td></tr><tr><td><code>Ctrl+R</code></td><td>Search prompt history</td></tr><tr><td><code>!</code></td><td>Enter shell mode from an empty input box</td></tr></tbody></table><h3 id="panels-and-sessions" tabindex="-1">Panels and sessions <a class="header-anchor" href="#panels-and-sessions" aria-label="Permalink to &quot;Panels and sessions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+T</code></td><td>Toggle the todo panel</td></tr><tr><td><code>Ctrl+B</code></td><td>Send the running command to the background</td></tr><tr><td><code>Ctrl+;</code> or <code>Ctrl+&#39;</code></td><td>Toggle the prompt-queue panel</td></tr><tr><td><code>Ctrl+S</code></td><td>Open the session list</td></tr><tr><td><code>Ctrl+L</code></td><td>Open the extensions dialog</td></tr><tr><td><code>Ctrl+G</code></td><td>Toggle the task panel</td></tr><tr><td><code>Ctrl+O</code></td><td>Toggle always-approve</td></tr><tr><td><code>Ctrl+N</code></td><td>New session (press twice)</td></tr><tr><td><code>Ctrl+M</code></td><td>Pick a model when the input box is not focused</td></tr><tr><td><code>Ctrl+\\</code></td><td>Open the Agent Dashboard</td></tr></tbody></table><h3 id="terminal-differences-important" tabindex="-1">Terminal differences (important) <a class="header-anchor" href="#terminal-differences-important" aria-label="Permalink to &quot;Terminal differences (important)&quot;">​</a></h3><ul><li>VS Code-family terminals (VS Code, Cursor, Windsurf, Zed): quit is <code>Ctrl+D</code> only, interject is <code>Ctrl+L</code>, half-page scroll is <code>Shift+D</code>, <code>Ctrl+L</code> does <strong>not</strong> open the extensions dialog (use <code>/plugins</code>), newline is <code>Alt+Enter</code></li><li>Apple Terminal: <code>Ctrl+O</code> also interjects</li><li>WezTerm: needs <code>enable_kitty_keyboard = true</code> for <code>Ctrl+Enter</code> and <code>Shift+Enter</code></li></ul><p>Letter keys in the scrollback (<code>j</code>/<code>k</code>/<code>g</code>/<code>e</code>/<code>y</code>/<code>/</code> and friends) require vim mode (<code>/vim-mode</code> or <code>[ui] vim_mode = true</code>); the arrow-key equivalents always work.</p><h2 id="configuration-files" tabindex="-1">Configuration files <a class="header-anchor" href="#configuration-files" aria-label="Permalink to &quot;Configuration files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>~/.grok/config.toml</code></td><td>User configuration (Windows: <code>%USERPROFILE%\\.grok\\config.toml</code>)</td></tr><tr><td><code>&lt;project&gt;/.grok/config.toml</code></td><td>Project configuration; <strong>only</strong> <code>[mcp_servers]</code>, <code>[plugins]</code>, <code>[permission]</code> are read</td></tr><tr><td><code>~/.grok/sandbox.toml</code> / <code>.grok/sandbox.toml</code></td><td>Custom sandbox profiles</td></tr><tr><td><code>~/.grok/hooks/*.json</code> / <code>&lt;project&gt;/.grok/hooks/*.json</code></td><td>Hook definitions</td></tr><tr><td><code>~/.grok/skills/</code> / <code>./.grok/skills/</code></td><td>Skill directories</td></tr><tr><td><code>~/.grok/plugins/</code> / <code>./.grok/plugins/</code></td><td>Plugin directories</td></tr><tr><td><code>~/.grok/agents/</code> / <code>.grok/agents/</code></td><td>Custom subagent types</td></tr><tr><td><code>~/.grok/personas/*.toml</code> / <code>.grok/personas/*.toml</code></td><td>Persona definitions</td></tr><tr><td><code>~/.grok/workflows/*.rhai</code> / <code>.grok/workflows/*.rhai</code></td><td>Workflows</td></tr><tr><td><code>~/.grok/sessions/</code></td><td>Session history (indexed by working directory)</td></tr><tr><td><code>~/.grok/worktrees/&lt;repo&gt;/&lt;name&gt;</code></td><td>Session worktrees</td></tr><tr><td><code>~/.grok/mcp_credentials.json</code></td><td>MCP OAuth tokens</td></tr><tr><td><code>~/.grok/trusted_folders.toml</code></td><td>Trusted project directories</td></tr><tr><td><code>~/.grok/logs/mcp/&lt;server&gt;.stderr.log</code></td><td>stderr of MCP stdio servers</td></tr><tr><td><code>/etc/grok/requirements.toml</code></td><td>System-level managed policy (the tamper lock is honored only from root-owned sources)</td></tr></tbody></table><p>Instruction files: the <code>AGENTS.md</code> family (<code>AGENTS.md</code> / <code>Agents.md</code> / <code>AGENT.md</code>) and the Claude family (<code>CLAUDE.md</code> / <code>Claude.md</code> / <code>CLAUDE.local.md</code> / <code>.claude/rules/</code>) are read from the cwd upward to the repository root.</p><h2 id="common-configuration-keys" tabindex="-1">Common configuration keys <a class="header-anchor" href="#common-configuration-keys" aria-label="Permalink to &quot;Common configuration keys&quot;">​</a></h2><p>Source: <a href="https://docs.x.ai/build/settings/reference" target="_blank" rel="noreferrer">Settings Reference</a></p><table tabindex="0"><thead><tr><th>Section</th><th>Key</th><th>Notes</th></tr></thead><tbody><tr><td><code>[models]</code></td><td><code>default</code></td><td>Model used by new sessions</td></tr><tr><td><code>[models]</code></td><td><code>allowed_models</code> / <code>hidden_models</code> / <code>disabled_models</code></td><td>Restrict selectable models (glob list / ID list)</td></tr><tr><td><code>[model.&lt;id&gt;]</code></td><td><code>model</code> / <code>base_url</code> / <code>name</code> / <code>env_key</code> / <code>api_backend</code></td><td>Custom or BYOK model</td></tr><tr><td><code>[model.&lt;id&gt;]</code></td><td><code>context_window</code></td><td>Context window size; affects when auto-compaction kicks in</td></tr><tr><td><code>[tools]</code></td><td><code>respect_gitignore</code></td><td>Default <code>false</code>; when <code>true</code>, search/read tools skip gitignored files</td></tr><tr><td><code>[toolset]</code></td><td><code>file_toolset</code></td><td><code>standard</code> (default) or <code>hashline</code></td></tr><tr><td><code>[toolset.bash]</code></td><td><code>timeout_secs</code> / <code>output_byte_limit</code> / <code>max_timeout_secs</code></td><td>Defaults <code>120</code> s / <code>20000</code> bytes / <code>36000</code> s</td></tr><tr><td><code>[toolset.bash]</code></td><td><code>auto_background_on_timeout</code></td><td>Default <code>true</code>; moves to background on timeout</td></tr><tr><td><code>[toolset.web_fetch]</code></td><td><code>allowed_domains</code> / <code>proxy_endpoint</code></td><td>Domain allowlist and egress proxy for <code>web_fetch</code></td></tr><tr><td><code>[sandbox]</code></td><td><code>profile</code> / <code>auto_allow_bash</code></td><td>Sandbox profile; skip bash prompts while the sandbox is active</td></tr><tr><td><code>[permission]</code></td><td><code>rules</code></td><td>allow / deny rules</td></tr><tr><td><code>[ui]</code></td><td><code>permission_mode</code></td><td><code>&quot;ask&quot;</code> / <code>&quot;auto&quot;</code> / <code>&quot;always-approve&quot;</code>; user config only</td></tr><tr><td><code>[ui]</code></td><td><code>disable_bypass_permissions_mode</code></td><td>Globally lock out always-approve (root-owned sources only)</td></tr><tr><td><code>[ui]</code></td><td><code>vim_mode</code></td><td>vim keys in the scrollback</td></tr><tr><td><code>[features]</code></td><td><code>web_fetch</code> / <code>lsp_tools</code> / <code>write_file</code> / <code>tool_search</code></td><td><code>lsp_tools</code> off by default; <code>write_file</code> / <code>tool_search</code> on</td></tr><tr><td><code>[subagents]</code></td><td><code>enabled</code> / <code>toggle</code> / <code>models</code></td><td>Master switch / per-type switch / per-type model routing</td></tr><tr><td><code>[memory]</code></td><td><code>enabled</code></td><td>Cross-session memory master switch, <strong>off by default</strong></td></tr><tr><td><code>[skills]</code> / <code>[plugins]</code></td><td><code>paths</code> / <code>disabled</code> / <code>enabled</code></td><td>Extra directories / discovered but inactive / explicitly enabled</td></tr><tr><td><code>[compat.claude]</code> / <code>[compat.cursor]</code></td><td><code>skills</code> / <code>rules</code> / <code>agents</code> / <code>mcps</code> / <code>hooks</code></td><td>Whether to scan those directories; all default <code>true</code></td></tr><tr><td><code>[dashboard]</code></td><td><code>enabled</code></td><td>Agent Dashboard master switch</td></tr><tr><td><code>[workflows]</code></td><td><code>enabled</code></td><td>Workflow master switch</td></tr><tr><td><code>[mcp_servers.&lt;name&gt;]</code></td><td><code>startup_timeout_sec</code> / <code>tool_timeout_sec</code></td><td>Defaults <code>30</code> / <code>6000</code> seconds</td></tr></tbody></table><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>GROK_HOME</code></td><td><code>~/.grok</code></td><td>Home for configuration, auth, sessions, skills, plugins, logs</td></tr><tr><td><code>XAI_API_KEY</code></td><td>—</td><td>API key when not using browser login (CI / headless)</td></tr><tr><td><code>GROK_DEFAULT_MODEL</code></td><td>directory / config</td><td>Default model for sessions</td></tr><tr><td><code>GROK_XAI_API_BASE_URL</code></td><td><code>https://api.x.ai/v1</code></td><td>xAI API base when authenticating with an API key</td></tr><tr><td><code>GROK_MODELS_BASE_URL</code></td><td>—</td><td>Custom inference base URL</td></tr><tr><td><code>GROK_DISABLE_AUTOUPDATER</code></td><td>unset</td><td>Set to disable auto-update (CI / containers)</td></tr><tr><td><code>GROK_SANDBOX</code></td><td><code>off</code></td><td>Sandbox profile, equivalent to <code>--sandbox</code></td></tr><tr><td><code>GROK_SANDBOX_AUTO_ALLOW_BASH</code></td><td><code>0</code></td><td>Auto-allow bash while the sandbox is active</td></tr><tr><td><code>GROK_RESPECT_GITIGNORE</code></td><td>follows config</td><td>Force search/read filtering by gitignore</td></tr><tr><td><code>GROK_WEB_FETCH</code></td><td><code>0</code></td><td>Enable the <code>web_fetch</code> tool, <strong>off by default (security)</strong></td></tr><tr><td><code>GROK_WEB_FETCH_PROXY</code></td><td>—</td><td>Egress proxy for <code>web_fetch</code></td></tr><tr><td><code>GROK_MEMORY</code></td><td><code>0</code></td><td>Cross-session memory</td></tr><tr><td><code>GROK_SUBAGENTS</code></td><td><code>0</code></td><td>Enable subagents / the task tool (<code>1</code>/<code>0</code>). The <a href="https://docs.x.ai/build/features/subagents" target="_blank" rel="noreferrer">subagents</a> page also says they are &quot;Enabled by default when the setting is unset.&quot; Those two official sentences disagree — do not guess which wins; check <code>grok inspect</code> on your machine.</td></tr><tr><td><code>GROK_WRITE_FILE</code></td><td><code>1</code></td><td>Set <code>0</code> to disable the <code>write</code> tool (read-only sessions)</td></tr><tr><td><code>GROK_TOOL_SEARCH</code></td><td><code>1</code></td><td>On-demand MCP tool discovery for large tool sets</td></tr><tr><td><code>GROK_LSP_TOOLS</code></td><td><code>0</code></td><td>LSP code-intelligence tools</td></tr><tr><td><code>GROK_AGENT</code></td><td><code>grok-build</code></td><td>Built-in agent name, profile, or absolute path to an agent definition</td></tr><tr><td><code>GROK_AGENT_DASHBOARD</code></td><td>—</td><td>Set <code>0</code> to disable the Agent Dashboard</td></tr><tr><td><code>GROK_WORKFLOWS</code></td><td>—</td><td>Set <code>0</code> to disable workflows</td></tr><tr><td><code>GROK_THEME</code></td><td>built-in</td><td>Color theme</td></tr><tr><td><code>GROK_MCP_STARTUP_TIMEOUT_SECS</code></td><td><code>30</code></td><td>Global MCP startup handshake timeout, in <strong>seconds</strong></td></tr><tr><td><code>MCP_TIMEOUT</code></td><td>same setting</td><td>Claude-compatible MCP startup timeout, in <strong>milliseconds</strong>; checked before the one above</td></tr><tr><td><code>GROK_LOG_FILE</code></td><td>—</td><td>Write logs to this path</td></tr><tr><td><code>RUST_LOG</code></td><td>—</td><td>Log filter (e.g. <code>debug</code>)</td></tr><tr><td><code>GROK_CRASH_HANDLER</code></td><td><code>0</code></td><td>Write panic reports to <code>$GROK_HOME/crash/</code></td></tr><tr><td><code>HTTPS_PROXY</code> / <code>HTTP_PROXY</code> / <code>NO_PROXY</code></td><td>system</td><td>Standard proxy variables</td></tr></tbody></table><p>The compatibility-scanner switches all default to on: <code>GROK_CURSOR_{SKILLS,RULES,AGENTS,MCPS,HOOKS}_ENABLED</code>, <code>GROK_CLAUDE_{SKILLS,RULES,AGENTS,MCPS,HOOKS}_ENABLED</code>.</p><p>Additional UI variables include <code>GROK_SHOW_THINKING_BLOCKS</code>, <code>GROK_GROUP_TOOL_VERBS</code>, <code>GROK_COLLAPSED_EDIT_BLOCKS</code>, <code>GROK_PROMPT_SUGGESTIONS</code>, <code>GROK_SCROLL_SPEED</code>, <code>GROK_SCROLL_MODE</code>, <code>GROK_SCROLL_LINES</code>, <code>GROK_INVERT_SCROLL</code>, <code>GROK_DEFAULT_SELECTED_PERMISSION</code>, <code>GROK_REMEMBER_TOOL_APPROVALS</code>, <code>GROK_MOUSE_REPORTING_TOGGLE</code>, <code>GROK_DISPLAY_REFRESH_AUTO_CADENCE</code>; full defaults are in the official <a href="https://docs.x.ai/build/settings/reference" target="_blank" rel="noreferrer">Settings Reference</a>.</p><h2 id="hook-events" tabindex="-1">Hook events <a class="header-anchor" href="#hook-events" aria-label="Permalink to &quot;Hook events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>When it fires</th></tr></thead><tbody><tr><td><code>SessionStart</code> / <code>SessionEnd</code></td><td>Session starts / ends</td></tr><tr><td><code>UserPromptSubmit</code></td><td>You submit a prompt</td></tr><tr><td><code>PreToolUse</code></td><td>A tool is about to run — <strong>the only blocking event</strong></td></tr><tr><td><code>PostToolUse</code> / <code>PostToolUseFailure</code></td><td>Tool finished / failed</td></tr><tr><td><code>PermissionDenied</code></td><td>The permission system denied a call</td></tr><tr><td><code>Stop</code> / <code>StopFailure</code></td><td>Turn ended / ended due to an API error</td></tr><tr><td><code>Notification</code></td><td>The agent emits a notification</td></tr><tr><td><code>SubagentStart</code> / <code>SubagentStop</code></td><td>Subagent starts / stops</td></tr><tr><td><code>PreCompact</code> / <code>PostCompact</code></td><td>Before / after conversation compaction</td></tr></tbody></table><p>Exit code 0 allows, exit code 2 blocks, and everything else (timeout, crash, malformed output) <strong>fails open</strong>.</p><h2 id="models-and-pricing" tabindex="-1">Models and pricing <a class="header-anchor" href="#models-and-pricing" aria-label="Permalink to &quot;Models and pricing&quot;">​</a></h2><p>Source: <a href="https://docs.x.ai/developers/models" target="_blank" rel="noreferrer">Models</a>. Prices are US dollars per million tokens.</p><table tabindex="0"><thead><tr><th>Model</th><th>Context</th><th>Input</th><th>Cached input</th><th>Output</th></tr></thead><tbody><tr><td><code>grok-4.6</code> (prompt &lt; 200k)</td><td>500k</td><td>$2.00</td><td>$0.50</td><td>$6.00</td></tr><tr><td><code>grok-4.6</code> (prompt ≥ 200k)</td><td>500k</td><td>$4.00</td><td>$1.00</td><td>$12.00</td></tr><tr><td><code>grok-build-0.1</code> (prompt &lt; 200k)</td><td>256k</td><td>$1.00</td><td>$0.20</td><td>$2.00</td></tr><tr><td><code>grok-build-0.1</code> (prompt ≥ 200k)</td><td>256k</td><td>$2.00</td><td>$0.40</td><td>$4.00</td></tr></tbody></table><p>Long-context billing rule: <strong>once a prompt reaches the threshold, every token in that request is billed at the higher tier</strong> — it is not just the excess that costs more.</p><p>Official model-selection advice:</p><blockquote><p>For everything else, including code, use Grok 4.6. It is the most intelligent and fastest model we&#39;ve built.</p></blockquote><p><code>grok-4.6</code> has a knowledge cutoff of 2026-02-01. Alias rules: <code>&lt;modelname&gt;</code> points at the latest stable release, <code>&lt;modelname&gt;-latest</code> at the latest release, and <code>&lt;modelname&gt;-&lt;date&gt;</code> pins a specific one.</p><p>Prices for other models (<code>grok-4.5</code>, <code>grok-4.3</code>, the <code>grok-4.20-*</code> series, Imagine image/video, Voice) are on the official page.</p><h2 id="high-quality-sources" tabindex="-1">High-quality sources <a class="header-anchor" href="#high-quality-sources" aria-label="Permalink to &quot;High-quality sources&quot;">​</a></h2><p>Last verified 2026-08-18. Ordered by reliability and freshness. <strong>The changelog can list commands before <a href="https://docs.x.ai/build/cli/reference" target="_blank" rel="noreferrer">CLI Reference</a> does</strong> (the research note recorded <code>grok du</code> and <code>grok trace</code> appearing on the changelog first) — check it first for behavior the docs do not mention.</p><h3 id="first-party-official" tabindex="-1">First-party official <a class="header-anchor" href="#first-party-official" aria-label="Permalink to &quot;First-party official&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://docs.x.ai/build/overview" target="_blank" rel="noreferrer">docs.x.ai/build/overview</a></td><td>Grok Build documentation entry point</td></tr><tr><td><a href="https://docs.x.ai/build/cli/reference" target="_blank" rel="noreferrer">docs.x.ai/build/cli/reference</a></td><td>Subcommands and flags</td></tr><tr><td><a href="https://docs.x.ai/build/cli/headless-scripting" target="_blank" rel="noreferrer">docs.x.ai/build/cli/headless-scripting</a></td><td>Headless and ACP</td></tr><tr><td><a href="https://docs.x.ai/build/cli/terminal-support" target="_blank" rel="noreferrer">docs.x.ai/build/cli/terminal-support</a></td><td>Terminal compatibility and diagnostics</td></tr><tr><td><a href="https://docs.x.ai/build/modes-and-commands" target="_blank" rel="noreferrer">docs.x.ai/build/modes-and-commands</a></td><td>Full mode and slash-command tables</td></tr><tr><td><a href="https://docs.x.ai/build/keyboard-shortcuts" target="_blank" rel="noreferrer">docs.x.ai/build/keyboard-shortcuts</a></td><td>Full key-binding table</td></tr><tr><td><a href="https://docs.x.ai/build/settings" target="_blank" rel="noreferrer">docs.x.ai/build/settings</a></td><td>Config layers and precedence</td></tr><tr><td><a href="https://docs.x.ai/build/settings/reference" target="_blank" rel="noreferrer">docs.x.ai/build/settings/reference</a></td><td>Full env var and TOML key tables</td></tr><tr><td><a href="https://docs.x.ai/build/enterprise" target="_blank" rel="noreferrer">docs.x.ai/build/enterprise</a></td><td>Managed config, SSO, ZDR, CI permission modes</td></tr><tr><td><a href="https://docs.x.ai/build/features/permissions" target="_blank" rel="noreferrer">docs.x.ai/build/features/permissions</a></td><td>Permission model</td></tr><tr><td><a href="https://docs.x.ai/build/features/sandbox" target="_blank" rel="noreferrer">docs.x.ai/build/features/sandbox</a></td><td>Sandbox profiles</td></tr><tr><td><a href="https://docs.x.ai/build/features/hooks" target="_blank" rel="noreferrer">docs.x.ai/build/features/hooks</a></td><td>Hook events and the script contract</td></tr><tr><td><a href="https://docs.x.ai/build/features/mcp-servers" target="_blank" rel="noreferrer">docs.x.ai/build/features/mcp-servers</a></td><td>MCP configuration</td></tr><tr><td><a href="https://docs.x.ai/build/features/skills-plugins-marketplaces" target="_blank" rel="noreferrer">docs.x.ai/build/features/skills-plugins-marketplaces</a></td><td>Skills / plugins / marketplaces</td></tr><tr><td><a href="https://docs.x.ai/build/features/sessions" target="_blank" rel="noreferrer">docs.x.ai/build/features/sessions</a></td><td>Sessions, fork, rewind, compact</td></tr><tr><td><a href="https://docs.x.ai/build/features/worktrees" target="_blank" rel="noreferrer">docs.x.ai/build/features/worktrees</a></td><td>Worktrees</td></tr><tr><td><a href="https://docs.x.ai/build/features/subagents" target="_blank" rel="noreferrer">docs.x.ai/build/features/subagents</a></td><td>Subagents and personas</td></tr><tr><td><a href="https://docs.x.ai/build/features/background-tasks" target="_blank" rel="noreferrer">docs.x.ai/build/features/background-tasks</a></td><td>Background tasks, <code>/loop</code>, monitors</td></tr><tr><td><a href="https://docs.x.ai/build/features/dashboard" target="_blank" rel="noreferrer">docs.x.ai/build/features/dashboard</a></td><td>Agent Dashboard</td></tr><tr><td><a href="https://docs.x.ai/developers/models" target="_blank" rel="noreferrer">docs.x.ai/developers/models</a></td><td>Model list and pricing</td></tr><tr><td><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a></td><td>grok.com / apps consumer overview</td></tr><tr><td><a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">docs.x.ai/developers/model-capabilities/imagine</a></td><td>Imagine API (images and video)</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/overview" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/overview</a></td><td>Grok Bot product entry</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/get-started" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/get-started</a></td><td>Grok Bot install and first task</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/computer-and-apps" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/computer-and-apps</a></td><td>Shared cloud computer</td></tr><tr><td><a href="https://docs.x.ai/grok-bot/faq" target="_blank" rel="noreferrer">docs.x.ai/grok-bot/faq</a></td><td>Grok Bot platforms, cost, memory</td></tr></tbody></table><h3 id="efficiency-tricks" tabindex="-1">Efficiency tricks <a class="header-anchor" href="#efficiency-tricks" aria-label="Permalink to &quot;Efficiency tricks&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Trick</th><th>Notes</th></tr></thead><tbody><tr><td><a href="https://docs.x.ai/llms.txt" target="_blank" rel="noreferrer">docs.x.ai/llms.txt</a></td><td>Single-file full-text mirror of the whole docs site; good for local grep or feeding a model (it is large — do not commit it to a repo). Last verified 2026-08-18, HTTP 200.</td></tr><tr><td><code>https://docs.x.ai/api/mcp</code></td><td>Official docs MCP endpoint (Streamable HTTP, stateless); tools <code>list_doc_pages</code> / <code>get_doc_page</code>. Browser GET/HEAD is not a docs page — 2026-08-18: HEAD 405, GET/POST 406, OPTIONS 204. Use an MCP client, not a browser.</td></tr><tr><td><code>grok inspect --json</code></td><td>Fastest way to answer &quot;what is actually loaded on this machine&quot;</td></tr></tbody></table><h3 id="versions-and-source" tabindex="-1">Versions and source <a class="header-anchor" href="#versions-and-source" aria-label="Permalink to &quot;Versions and source&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://x.ai/build/changelog" target="_blank" rel="noreferrer">x.ai/build/changelog</a></td><td>Changelog; updated faster than the docs site</td></tr><tr><td><a href="https://x.ai/news/grok-build-cli" target="_blank" rel="noreferrer">x.ai/news/grok-build-cli</a></td><td>Launch announcement (2026-05-25, early beta)</td></tr><tr><td><a href="https://x.ai/news/grok-4-6" target="_blank" rel="noreferrer">x.ai/news/grok-4-6</a></td><td>Grok 4.6 announcement (mentions time-boxed 2x included usage in Grok Build; no standing quota number)</td></tr><tr><td><a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a></td><td>Consumer Grok (chat / Imagine / voice)</td></tr><tr><td><a href="https://grok.com/imagine" target="_blank" rel="noreferrer">grok.com/imagine</a></td><td>Consumer Imagine</td></tr><tr><td><a href="https://x.ai/grok/build-mode" target="_blank" rel="noreferrer">x.ai/grok/build-mode</a></td><td>Build Mode marketing (not Grok Build CLI)</td></tr><tr><td><a href="https://x.ai/news/grok-build-mode" target="_blank" rel="noreferrer">x.ai/news/grok-build-mode</a></td><td>Build Mode launch; SuperGrok Heavy Early Beta; grok.me publish host</td></tr><tr><td><a href="https://x.ai/bot" target="_blank" rel="noreferrer">x.ai/bot</a></td><td>Grok Bot marketing + downloads</td></tr><tr><td><a href="https://x.ai/news/introducing-grok-bot" target="_blank" rel="noreferrer">x.ai/news/introducing-grok-bot</a></td><td>Grok Bot launch (2026-08-11, beta)</td></tr><tr><td><a href="https://github.com/xai-org/grok-build" target="_blank" rel="noreferrer">github.com/xai-org/grok-build</a></td><td>Source (Rust, Apache-2.0); <strong>external PRs are not accepted</strong>, feedback goes through <code>/feedback</code></td></tr><tr><td><a href="https://github.com/xai-org/plugin-marketplace" target="_blank" rel="noreferrer">github.com/xai-org/plugin-marketplace</a></td><td>Official plugin marketplace catalog</td></tr><tr><td><a href="https://www.npmjs.com/package/@xai-official/grok" target="_blank" rel="noreferrer">npmjs.com/package/@xai-official/grok</a></td><td>Release cadence and version history</td></tr></tbody></table><p><strong>Access note</strong> (re-checked 2026-08-18): <code>x.ai/build</code> and <code>x.ai/build/changelog</code> return 403 to command-line <code>curl</code> (Cloudflare). <code>x.ai/news/grok-build-cli</code> and <code>x.ai/cli/install.sh</code> returned 200. <code>docs.x.ai</code> pages above returned 200. npmjs.com HTML returned 403; the registry JSON at <code>https://registry.npmjs.org/@xai-official/grok</code> is readable.</p><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Grok learning map</a></li><li><a href="./grok-cli.html">Grok Build tutorial</a></li><li><a href="./grok-cookbook.html">Grok Build cookbook</a></li><li><a href="./grok-glossary.html">Grok Build glossary</a></li><li><a href="./grok-bot.html">Grok Bot</a></li></ul>`,85)])])}const k=e(a,[["render",s]]);export{b as __pageData,k as default};
